INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M01','hard_constraint_violations','件','小','独立検証器で数えた必須条件違反。未検証はnull。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M02','uncovered_staff_minutes','人分','小','必要役割別・時間帯別の必要人数との差を時間積算。資格の二重計上をしない。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M03','validated_feasible_rate','比率','大','既知可解の全試行に対する独立検証済み可解結果の割合。打切り・失敗も分母に含める。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M04','time_to_first_feasible_s','秒','小','最初の検証済み可解解まで。未発見は打切りとして上限時間と共に記録。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M05','total_wall_time_s','秒','小','要求開始から結果取得まで。待機・計算・通信等を含み、成功/失敗別に集計。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M06','solver_time_s','秒','小','純計算時間。非公開SaaSの場合はnull。総待ち時間と混同しない。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M07','manual_edit_minutes','分','小','生成後に管理者が公開可能状態へ修正する時間。修正後の再検証を含む。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M08','onboarding_person_hours','人時','小','初期データ整備・設定・教育の実働。毎月作業と分ける。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M09','monthly_total_person_minutes','人分','小','希望回収・入力・確認・修正・承認・配付の月次合計。単純な計算待機は別記。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M10','preference_fulfillment_rate','比率','大','事前に定義した希望の充足数/対象希望数。承認済み休暇等の必須条件を除く。分母0はNA。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M11','worst_employee_preference_rate','比率','大','対象希望がある職員の希望充足率の最小値。対象者集合と除外を保存。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M12','fte_adjusted_burden_dispersion','指標値','小','合意した契約時間・勤務可能枠で補正した負担のばらつき。指標の式を固定。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M13','historical_burden_dispersion','指標値','小','同じ履歴期間で補正した複数月の負担分散。前年実績等の窓を記録。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M14','changed_employees','人','小','基準勤務表に対して少なくとも1件の変更を受ける職員数。欠勤者を含むか事前指定。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M15','changed_assignments','件','小','共通の勤務枠IDに対する割当変更数。単に表示セルを増減して数えない。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M16','pinned_assignment_violations','件','小','固定済み勤務の変更件数。原則0をゲート条件にする。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M17','false_infeasibility_rate','比率','小','既知可解の試行を誤って不可解と断定した割合。未判定と混同しない。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M18','explanation_revalidation_rate','比率','大','根拠付き矛盾説明・調整案について再検証で妥当と確認できた割合。文章の自然さで代替しない。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M19','certified_absolute_gap','目的関数の単位','小','同一目的・同一問題の実行可能値と証明済み境界の差。境界未提供はnull。');
INSERT INTO "metric_catalog" ("metric_id","field_key","unit","preferred_direction","definition") VALUES ('M20','common_evaluator_score','共通評価点','小','共通制約・共通重み・共通評価器で外部再計算。各社固有スコアを直接比較しない。');
INSERT INTO "research_assets" ("asset_id","asset_type","title","version_label","maturity","attributes_json","notes") VALUES ('B02-AS01','study','Lantum In-Genius / Guy’s and St Thomas’s 集中治療部門','B02資料確認','vendor_before_after_case','{"product_id":"US13","study_design":"vendor_before_after_case","baseline_year":2024,"physicians":85,"fte":78,"rosters":5,"followup_months":6,"currency":"GBP","reported_savings":30000,"study_leave_approved_pct":100,"annual_leave_honoured_pct":98}','固定パターン・短時間勤務者の配置運用も変更。分母・対照群は不明。看護師での性能試験ではない。');
INSERT INTO "research_assets" ("asset_id","asset_type","title","version_label","maturity","attributes_json","notes") VALUES ('B02-AS02','study','Northern Light Health Clairvia 教育資料の公開','B02資料確認','customer_training_index','{"product_id":"US15","study_design":"customer_training_index","outcome_measured":false}','患者割当・必要度・配置・監査の教材目次。教材全文未読。利用機関による公開資料だが現行販売状況・削減率の証拠ではない。');
INSERT INTO "research_assets" ("asset_id","asset_type","title","version_label","maturity","attributes_json","notes") VALUES ('B02-AS03','technology','シフト屋さん HTTP API / MCP 無料β仕様','B02資料確認','public_beta','{"product_id":"JP28","maturity":"public_beta","source_code_of_solver_verified":false,"independently_tested":false}','暗黙の連勤条件と不足を残す返却を確認。接続部品の公開と本体の商用利用権は別確認。');
INSERT INTO "research_assets" ("asset_id","asset_type","title","version_label","maturity","attributes_json","notes") VALUES ('B02-AS04','study','Allocate Optima 英国G-Cloud14 料金・契約仕様','B02資料確認','supplier_procurement_declaration','{"product_id":"US11","study_design":"supplier_procurement_declaration","document_date":"2024-05-07","independent_efficacy_evidence":false}','料金帯・小規模枠の除外機能をPDF画像で確認。現在の一般販売料金や独立した性能証明ではない。');
INSERT INTO "research_assets" ("asset_id","asset_type","title","version_label","maturity","attributes_json","notes") VALUES ('CASE01','study','那覇市立病院 / JP01',NULL,'vendor_case_not_independently_tested','{"case_id": "CASE01", "limitations": "導入時に希望休回数ルールも変更。システム単独の因果効果は分離できない。見出し8割と本文の概数が異なるため本文を採用。", "organization": "那覇市立病院", "pid": "JP01", "result": "8時間程度→約2時間（担当者コメント）", "scope": "対象の部署人数・期間は未公表", "sid": "W026"}','導入時に希望休回数ルールも変更。システム単独の因果効果は分離できない。見出し8割と本文の概数が異なるため本文を採用。');
INSERT INTO "research_assets" ("asset_id","asset_type","title","version_label","maturity","attributes_json","notes") VALUES ('CASE02','study','特養パール代官山 / JP07',NULL,'vendor_case_not_independently_tested','{"case_id": "CASE02", "limitations": "実時間の前後値・独立計測なし。採用成果は他施策の影響を分離できない。", "organization": "特養パール代官山", "pid": "JP07", "result": "作成時間が半分以下、シフト作成残業ほぼゼロとのコメント", "scope": "職員33人・入居50名＋短期10床、2026年7月公開、導入約1年", "sid": "W027"}','実時間の前後値・独立計測なし。採用成果は他施策の影響を分離できない。');
