INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0001','B03-20261011-REV001','B03-20261011-EV0001','前文・第1条',NULL,'提供主体は株式会社KakuKaku。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0002','B03-20261011-REV001','B03-20261011-EV0002','第2条・第5条',NULL,'施設管理者・リーダーが業務上必要な範囲で所属メンバーの勤務を閲覧し、範囲は施設設定に依存する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0003','B03-20261011-REV001','B03-20261011-EV0003','第2条・第4条',NULL,'ゲスト利用では施設アカウントなしで個人の勤務・私用予定を記録できる。施設運用とは別形態。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0004','B03-20261011-REV001','B03-20261011-EV0004','第4条',NULL,'ゲストの記録は端末だけに保存され、サーバー保存・バックアップは行わない。端末変更・アプリ削除では復元できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0005','B03-20261011-REV001','B03-20261011-EV0005','第4条',NULL,'施設アカウントへログインしても、既存のゲスト記録がクラウドへ保存されるわけではない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0006','B03-20261011-REV001','B03-20261011-EV0006','第8条',NULL,'規約は計算結果の法令適合・配置充足を保証せず、最終確認の責任を施設に置いている。独立検査機能の有無は未確定。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0007','B03-20261011-REV001','B03-20261011-EV0007','第9条',NULL,'保守・障害等では予告なく中断し得る。終了時は合理的期間で事前通知するが、数値SLAは本文にない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0008','B03-20261011-REV001','B03-20261011-EV0008','第6条・第7条',NULL,'許諾なしの複製・改変・頒布、およびソース解析は禁止事項として掲げる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0009','B03-20261011-REV002','B03-20261011-EV0009','対応制約・skill_levels',NULL,'業務別スキルレベルが0の職員は、その業務へ配置できないハード条件。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0010','B03-20261011-REV002','B03-20261011-EV0010','対応制約・skill_support',NULL,'初心者に熟練者を同席させるスキルサポートを必須または希望条件として指定できる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0011','B03-20261011-REV002','B03-20261011-EV0011','対応制約・manager_demand',NULL,'シフト・日ごとの責任者人数を指定でき、下限は必須、上限は希望条件。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0012','B03-20261011-REV002','B03-20261011-EV0012','対応制約・employee_pairings',NULL,'職員ペアの同時配置禁止をハード条件にできる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0013','B03-20261011-REV002','B03-20261011-EV0013','対応制約・cross_shift_demands',NULL,'複数シフトを横断する合計人数条件を指定できる。休憩中の人数保証とは別確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0014','B03-20261011-REV002','B03-20261011-EV0014','対応制約・fairness_groups',NULL,'最大4つの負担配分グループを独立に指定でき、均等化の重みを調整できる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0015','B03-20261011-REV002','B03-20261011-EV0015','対応制約・available_weekdays',NULL,'曜日別勤務可否と担当可能シフトを必須条件にできる。日跨ぎは勤務開始日の曜日で判定する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0016','B03-20261011-REV002','B03-20261011-EV0016','対応制約・weekly_working_hours_limit',NULL,'シフト時刻から算出する週間勤務時間上限を必須または希望条件にできる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0017','B03-20261011-REV002','B03-20261011-EV0017','対応制約・fixed_assignments',NULL,'日別の固定割当は必須条件として指定できる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0018','B03-20261011-REV002','B03-20261011-EV0018','対応制約一覧',NULL,'配置下限、固定割当、担当可否等と、希望・上限等の強制力を入力フィールド別に区別する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0019','B03-20261011-REV002','B03-20261011-EV0019','HTTP API直接・非同期',NULL,'概ね25人を超える問題では非同期の202・job_idを返し、後続の取得APIで結果を確認する仕様。計算時間は提供者説明で実測していない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0020','B03-20261011-REV002','B03-20261011-EV0020','HTTP API直接・APIスキーマ',NULL,'入力検証、計算要求、ジョブ結果取得、利用枠取得を公開APIで扱い、OpenAPI 3.1スキーマを公開する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0021','B03-20261011-REV002','B03-20261011-EV0021','クイックスタート・接続解除',NULL,'APIキーによる接続とOAuthによるリモートMCP接続を説明し、接続アプリは管理画面で解除可能。SSO/MFA全般の保証ではない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0022','B03-20261011-REV002','B03-20261011-EV0022','料金',NULL,'βは無料だがキーごとに利用枠があり、計算で消費する。追加枠は依頼制で正式版料金は未発表。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0023','B03-20261011-REV002','B03-20261011-EV0023','末尾・β仕様変更',NULL,'β期間の仕様は事前通知なしで変更され得る。変更はGitHubで告知すると説明する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0024','B03-20261011-REV003','B03-20261011-EV0024','100店舗以上向け・自動作成',NULL,'大規模向けの案内に勤務表の自動作成を掲載。希望回収・転記だけとは区別できるが、具体的な最適化条件は未公開。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0025','B03-20261011-REV003','B03-20261011-EV0025','規模別案内',NULL,'100店舗未満向けと100店舗以上向けを分け、後者に自動作成・専用アプリ・専任支援を説明する。利用可否は契約確認が必要。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B03-20261011-OBS0026','B03-20261011-REV003','B03-20261011-EV0026','8つの特徴・労務リスク',NULL,'連勤と夜勤明けの自動検知を掲載。勤務間休息を実時刻で保証するかは別確認。','supports','official_page_body_review','2026-10-11');
