INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0316','B04-20261011-REV035','B04-20261011-EV0316','料金プラン',NULL,'料金プランの金額は画像表示で、今回取得した本文だけでは確定できない。契約・オプション条件は別記録。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0317','B04-20261011-REV035','B04-20261011-EV0317','FAQ',NULL,'限定無料プランは試用・解約後の移行先として案内。開始時の直接選択、無料で使える機能は未確定。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0318','B04-20261011-REV036','B04-20261011-EV0318','第14条',NULL,'契約人数は最低10人、5人刻み。契約途中の増員は残期間の差額を請求し、減員・返金は行わない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0319','B04-20261011-REV036','B04-20261011-EV0319','第7条',NULL,'有料契約は1年間・年額前払い、自動更新。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0320','B04-20261011-REV036','B04-20261011-EV0320','第7条',NULL,'更新を止める申出は終了日の30日前まで。解約後は限定無料プランへ移行する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0321','B04-20261011-REV036','B04-20261011-EV0321','第27条',NULL,'必要な情報は契約終了前にダウンロードすること、終了後の提供はしない旨を規定。設定・履歴を含む全量出口を保証する記述ではない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0322','B04-20261011-REV036','B04-20261011-EV0322','第27条',NULL,'6か月の未使用等でデータを削除することがあり、削除後は復旧できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0323','B04-20261011-REV036','B04-20261011-EV0323','第11条',NULL,'API利用は提供者の許可と限定的な権利に基づく。連携の正確性・即時性を保証せず、終了後は接続できない。','supports','official_page_body_review','2026-10-11');
