INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0333','B04-20261011-REV037','B04-20261011-EV0333','KING OF TIME設定',NULL,'KING OF TIMEへの夜勤出力は、連続1勤務と夜勤・明けの別勤務の設定を選ぶ。','supports','official_page_body_review','2026-10-11');
