INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B04-20261011-OBS0335','B04-20261011-REV038','B04-20261011-EV0335','p2 §4 / §9',NULL,'有人の操作サポートは平日10〜18時、土日祝・お盆・年末年始を除く。問い合わせ回答を4営業日以上待たせない努力目標。ホームページの相談時間とは対象を分ける。','supports','official_page_body_review','2026-10-11');
