INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0065','B05-20261011-REV010','B05-20261011-EV0065','Revoke token / Disconnect',NULL,'接続解除時は認可取消用エンドポイントへRefresh Tokenを送る仕様が公開されている。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0066','B05-20261011-REV010','B05-20261011-EV0066','Requirements and limitations',NULL,'Open APIはHTTPSを要求する。Refresh Tokenは期限なしと説明されるが、利用者が権限を取り消すと再認可が必要。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0067','B05-20261011-REV011','B05-20261011-EV0067','Rate limit table / How to decode example',NULL,'制限表はポータルごと20要求/秒・750/分、Client IDごと100/秒・2000/分とするが、下の例はポータル10/秒と記す。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0068','B05-20261011-REV011','B05-20261011-EV0068','Viewing the status of the rate limit',NULL,'制限超過はHTTP429を返し、reset・remaining・limitの応答ヘッダーで再試行時点を確認する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0069','B05-20261011-REV011','B05-20261011-EV0069','A request will always contain one client id and portal',NULL,'1要求がポータルとClient IDの両方のカウンターを消費する。顧客別とアプリ全体の枠を分けて管理する必要がある。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0070','B05-20261011-REV012','B05-20261011-EV0070','Labor rules defined in agreement templates',NULL,'契約テンプレート内の労働ルールは既定では自動割当に反映されず、導入担当による有効化が必要。選択したルールのみ評価し、以後の設定変更は自動反映する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0071','B05-20261011-REV012','B05-20261011-EV0071','Max hours/day; Minimum/Max hours/week',NULL,'日上限は日跨ぎ勤務の時間を両日に分配する一方、週上限・下限はその週に開始した勤務を基準に集計する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0072','B05-20261011-REV012','B05-20261011-EV0072','Min REST; Minimum rest/week',NULL,'日休息はMin Restチェックの有無で、連続日の勤務間休息と日区切りを考慮する連続休息に分かれる。週休息は固定週またはローリング期間を設定できる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0073','B05-20261011-REV012','B05-20261011-EV0073','Max days; Free days',NULL,'最大連続勤務日数と、その上限まで勤務した後の最低連続休日を契約レベルで設定する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0074','B05-20261011-REV012','B05-20261011-EV0074','Maximum work hours w/o breaks; Minimum/Maximum break minutes',NULL,'必要休憩がない勤務、休憩の最小・最大時間を満たさない勤務は割当できない。休憩中の資格別実効人数の検査はこの説明では確認できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0075','B05-20261011-REV012','B05-20261011-EV0075','Minimum shift length',NULL,'期間別に複数の最低勤務長を設定した場合、自動割当は最小値を計画期間全体の最低長として使う。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0076','B05-20261011-REV012','B05-20261011-EV0076','Labor rules defined in Pythia',NULL,'追加ルールはPythia内でベンダーが設定・保守する。ユニット、勤務種別、職員、契約、年齢群ごとに適用でき、初期導入後の追加もベンダー対応。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0077','B05-20261011-REV012','B05-20261011-EV0077','Rule adherence and preferences',NULL,'各ルールを必須または希望に分け、必須は割当時に違反させず、希望間は重みで優先度を設定する。優先度の要望は顧客、実設定は導入担当が担う。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0078','B05-20261011-REV013','B05-20261011-EV0078','Introduction; warning details',NULL,'実行完了でも条件により不十分な結果になることがあり、対象ユニットの警告を通知と詳細パネルで確認する。完了は全枠充足を意味しない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0079','B05-20261011-REV013','B05-20261011-EV0079','Auto Schedule / Auto Assign warnings',NULL,'必要勤務時間と稼働可能時間の差、配置可能職員がいない勤務、対象勤務がない職員などの原因と対応例を表示する。最小矛盾集合の証明は記載されない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0080','B05-20261011-REV013','B05-20261011-EV0080','No active agreements; headcount requirements',NULL,'有効な契約がない場合は勤務を作らず完了する。必要人数条件がない勤務種別も作成対象にならない場合がある。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0081','B05-20261011-REV013','B05-20261011-EV0081','Fixed shifts assigned to ineligible employees',NULL,'不適格な職員に固定勤務が割り当て済みの場合も警告対象として説明する。固定した値の妥当性が自動的に保証されるわけではない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0082','B05-20261011-REV013','B05-20261011-EV0082','Auto Assign warning list',NULL,'計画の一部で契約が無効、勤務種別が非アクティブ、対象期間に未割当勤務がない場合を区別して警告する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0083','B05-20261011-REV013','B05-20261011-EV0083','Contradictory shift/break rules',NULL,'勤務長・休憩ルールの矛盾など、Quinyx画面外で設定される条件の変更はベンダーに連絡する運用としている。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0084','B05-20261011-REV014','B05-20261011-EV0084','Before you start; Preparing Your Shifts',NULL,'手作成、テンプレート、取込で事前に用意した未割当勤務に職員を配置する。勤務時刻・枠そのものの自動生成とは分けて扱う。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0085','B05-20261011-REV014','B05-20261011-EV0085','Automatically Assigning Shifts',NULL,'自動割当した勤務は草案になる。公開済み勤務への即時通知を伴うとはこの手順から確認できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0086','B05-20261011-REV014','B05-20261011-EV0086','Overlapping shifts',NULL,'同じ職員に時間が重なる勤務を割り当てないと説明する。施設間の移動時間・兼務者の集計算式は未確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0087','B05-20261011-REV014','B05-20261011-EV0087','Approved Time Off; Unavailability; toggles',NULL,'承認済み休暇と職員の勤務不可を考慮する。ただし勤務不可の考慮は実行前に切替可能。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0088','B05-20261011-REV014','B05-20261011-EV0088','Shift Qualification; toggles',NULL,'勤務またはJobに設定された適格性を考慮するが、その考慮を実行前に切り替えられる。医療資格の期限判定やスキル混成の算式は未確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0089','B05-20261011-REV014','B05-20261011-EV0089','Fairness',NULL,'公平性は職員間の勤務数を揃えることを目指すと説明する。契約時間比、夜勤負担、複数月の補正は記載されない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0090','B05-20261011-REV014','B05-20261011-EV0090','Work preferences',NULL,'勤務希望は可能な場合に反映するが、他のルールより優先しない。目的関数の数式や重み値は非公開。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0091','B05-20261011-REV014','B05-20261011-EV0091','Schedule Rules; Before you start',NULL,'設定した勤務時間・勤務数・休息ルールを自動割当では破らないと説明する。ルールは事前設定が必要。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0092','B05-20261011-REV014','B05-20261011-EV0092','FAQ: X shifts weren’t assigned',NULL,'割当できない勤務数を通知し、その勤務は未割当欄に残る。全勤務への配置は目標であり充足保証ではない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0093','B05-20261011-REV014','B05-20261011-EV0093','FAQ: schedule part of shifts',NULL,'一部の勤務を人が先に割り当て、残りを自動割当する運用を案内している。固定ロックの仕様とは区別する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0094','B05-20261011-REV014','B05-20261011-EV0094','FAQ: redo distribution',NULL,'自動割当の解除または再配分を選べる。任意の過去版復元・同時編集の衝突処理は未確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0095','B05-20261011-REV014','B05-20261011-EV0095','Next up',NULL,'前回勤務表との類似性と未処理のOpen Shift申請の考慮は次期開発項目として掲載され、提供済みとは扱わない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0096','B05-20261011-REV015','B05-20261011-EV0096','Admin permissions',NULL,'勤務ルールの設定にはJob Scheduling権限、対象勤務表へのアクセスと利用者詳細の管理権限が必要。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0097','B05-20261011-REV015','B05-20261011-EV0097','Company Policies; Custom Rules',NULL,'グループ方針と個人の例外ルールで、週勤務時間、日勤務数、勤務間休息を設定できる。新規職員への既定方針の自動適用も選べる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0098','B05-20261011-REV015','B05-20261011-EV0098','Assign rules; policy conflicts',NULL,'ルールは全勤務表または指定勤務表、Job、タグに適用できる。既存方針との重複時は追加または置換を選ぶ。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0099','B05-20261011-REV015','B05-20261011-EV0099','Prevent users from exceeding this rule when claiming shifts',NULL,'利用者がルール超過となる勤務を応募できない設定を選択できる。管理者承認が必要な募集でも、この応募制限は有効と説明する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0100','B05-20261011-REV015','B05-20261011-EV0100','Manual scheduling; statistics; Issues',NULL,'管理者の手動操作はPCでは草案保存・公開時、モバイルでは配置時に警告する。統計とIssuesでも違反を確認する。自動割当の必須遵守とは別の挙動。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0101','B05-20261011-REV015','B05-20261011-EV0101','Shift quotas',NULL,'Shift Quotasは利用者が応募するOpen Shiftの週最低数を設定する機能。人数不足を全体最適化する機能とは分ける。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0102','B05-20261011-REV015','B05-20261011-EV0102','Quota progress; notify users',NULL,'最低応募数は利用者／グループ、曜日・時間帯で対象を指定し、進捗バーや未達表示から本人へ通知できる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0103','B05-20261011-REV015','B05-20261011-EV0103','Manage policies',NULL,'方針の編集、複製、割当変更、一時無効化・再有効化を案内する。旧版の再現性・保存期間は未記載。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0104','B05-20261011-REV015','B05-20261011-EV0104','FAQ: different schedule limitations per user',NULL,'Schedule Limitationsは同じ勤務表全体に適用するため、その設定を同じ表内で職員別に変えられない。個人Custom Rulesとは別機能。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0105','B05-20261011-REV015','B05-20261011-EV0105','Schedule limitations availability',NULL,'勤務表全体のSchedule LimitationsはOperations Expertで提供すると説明する。各個人ルールのプラン境界は個別確認が必要。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0106','B05-20261011-REV015','B05-20261011-EV0106','Short Notice Alerts',NULL,'週開始前の指定時間内の作成・変更・公開をShort Notice Alertsとして警告でき、時刻・Job・場所・配置の変更を対象にする。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0107','B05-20261011-REV016','B05-20261011-EV0107','Set Regular Working Hours',NULL,'職員プロファイルまたは会社方針で曜日ごとに複数の通常勤務時間帯を設定し、勤務不可を自動生成する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0108','B05-20261011-REV016','B05-20261011-EV0108','Overnight working hours',NULL,'日跨ぎの通常勤務時間帯は当日24時までと翌日0時以降に分けて入力する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0109','B05-20261011-REV016','B05-20261011-EV0109','Time zone',NULL,'通常勤務時間帯にはタイムゾーンを設定でき、既定ではアカウントのタイムゾーンを使う。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0110','B05-20261011-REV016','B05-20261011-EV0110','Impact on scheduling; FAQ',NULL,'自動割当は通常勤務時間帯内に配置する。管理者による時間帯外の手動配置は競合表示を伴って可能と説明する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0111','B05-20261011-REV016','B05-20261011-EV0111','Track changes',NULL,'会社方針の作成・編集・削除・割当はCompany Activity Log、個人の変更はUser Timelineに記録する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0112','B05-20261011-REV016','B05-20261011-EV0112','FAQ: policies limits; Time Clock and Time Off',NULL,'Limited Operationsは方針を2件まで、Basic以上は無制限と案内する。Time Clock／Time Offへの通常勤務時間帯の適用は今後の予定として記載する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0113','B05-20261011-REV017','B05-20261011-EV0113','Time Clock; reports',NULL,'Time Clockは最大6個、レポートはTime Clockごとに3個までと説明する。勤務表の上限とは別のモジュール上限。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0114','B05-20261011-REV017','B05-20261011-EV0114','Custom timesheet export',NULL,'勤務時間表のCSVテンプレートを個別に構成できる。勤務表・希望・ルールの全量出力保証とは別に扱う。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0115','B05-20261011-REV017','B05-20261011-EV0115','Cross-schedule issues',NULL,'複数勤務表に所属する職員の重複勤務をCross-schedule issuesで警告する。複数表の同時最適化はこの説明では確認できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0116','B05-20261011-REV017','B05-20261011-EV0116','Shift Layers',NULL,'Shift Layersで勤務内のリソース・追加情報を扱う。リソースの自動最適化としては説明されていない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0117','B05-20261011-REV018','B05-20261011-EV0117','Permissions',NULL,'勤務ルールの設定はAdminまたはManagerが行う。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0118','B05-20261011-REV018','B05-20261011-EV0118','Definition of a day/week',NULL,'1日はアカウントの業務日開始時刻からの24時間、1週は設定した起点からの7日間。連勤日数・週勤務日数は勤務の開始日で数える。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0119','B05-20261011-REV018','B05-20261011-EV0119','Overnight shift example',NULL,'月曜に開始して火曜に終わる勤務は、連勤日数や勤務日数の算定では月曜だけに所属する。日別時間外計算の時間分割とは異なる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0120','B05-20261011-REV018','B05-20261011-EV0120','Minimum time between shifts',NULL,'同じ業務日内の最低勤務間隔は1〜12時間、異なる業務日間は1〜18時間の範囲で設定する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0121','B05-20261011-REV018','B05-20261011-EV0121','Maximum consecutive days; Maximum days per week',NULL,'最大連続勤務日数は1〜7日、週最大勤務日数は1〜6日の設定範囲としている。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0122','B05-20261011-REV018','B05-20261011-EV0122','Employee scheduling; manual scheduling',NULL,'勤務応募では違反につながるOpenShift／交換・譲渡候補を表示せず、違反となる交換相手も選択できない。一方、管理者の手作成では警告のあるテンプレートを選べる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0123','B05-20261011-REV018','B05-20261011-EV0123','Manual scheduling; publishing',NULL,'手動でのドラッグ変更時に違反アイコンを表示し、公開確認画面にも対象職員と懸念を一覧表示する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0124','B05-20261011-REV018','B05-20261011-EV0124','Auto Assign',NULL,'Auto Assignは有効な勤務ルールを自動考慮するため、設定によって一部勤務が未割当になる場合がある。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0125','B05-20261011-REV019','B05-20261011-EV0125','Hosting',NULL,'基盤にAWSを利用すると説明する。保管・処理・バックアップの具体的な国やリージョンはこの本文にない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0126','B05-20261011-REV019','B05-20261011-EV0126','Encryption',NULL,'Webとモバイルの通信をTLSで暗号化すると説明する。保存時暗号化の鍵管理などは別途確認が必要。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0127','B05-20261011-REV019','B05-20261011-EV0127','Mobile Two-Step Verification',NULL,'Mobile Two-Step Verificationを説明する。管理者のWeb認証にも必須化できるか、SSOとの併用条件は未確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0128','B05-20261011-REV019','B05-20261011-EV0128','Backups',NULL,'複数ディスクへの即時保存に加えて日次バックアップと復元テストの手順を説明する。RTO・RPOの数値保証は未確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0129','B05-20261011-REV019','B05-20261011-EV0129','SLA',NULL,'When I WorkとしてSLAは提供しないと明記する。ホスティング先の99.9%保証は同社サービス全体の稼働保証とは扱わない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0130','B05-20261011-REV020','B05-20261011-EV0130','Shifts / List Shifts / Create Shift',NULL,'勤務の一覧、作成、更新、複数削除を公開し、W-Token認証を指定する。勤務一覧では非公開勤務の取得に監督権限、全拠点OpenShift取得にManager/Admin権限が必要。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0131','B05-20261011-REV020','B05-20261011-EV0131','Introduction',NULL,'定期同期はWebhook購読を推奨し、大量の頻繁な取得はAPI制限に達する可能性があると説明する。再送・順序保証の数値は未確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0132','B05-20261011-REV020','B05-20261011-EV0132','List Shifts / deleted',NULL,'勤務取得で期間内に削除された勤務IDの一覧も返す指定がある。職員同期全体の整合性保証とは分ける。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0133','B05-20261011-REV020','B05-20261011-EV0133','Create Shift schema',NULL,'勤務スキーマに公開日時、通知日時、確認済みフラグと確認日時を公開する。確認機能が有効な場合の値で、通知到達率の保証ではない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0134','B05-20261011-REV020','B05-20261011-EV0134','List Shifts / limit_by_rules',NULL,'勤務取得にlimit_by_rulesを指定すると、アカウントの勤務ルールで応募可能なOpenShiftのみを返す仕様。すべてのAPI書込に同じ制限があるとは推定しない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0135','B05-20261011-REV020','B05-20261011-EV0135','Create Shift / breaks',NULL,'予定休憩の配列を更新する場合、要求に含めない既存休憩は削除される。休憩中の現場人数を自動検査するという意味ではない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0136','B05-20261011-REV021','B05-20261011-EV0136','Employee management',NULL,'職員の作成、取得、更新、非アクティブ化をAPIで行う。一覧は基本項目で、ID指定取得ではカスタム項目を含む詳細を返す。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0137','B05-20261011-REV021','B05-20261011-EV0137','Employee data scopes',NULL,'SSN・銀行口座・生年月日は別の専用スコープとパラメータが必要。一般職員取得がすべての機微項目を返すとは扱わない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0138','B05-20261011-REV021','B05-20261011-EV0138','Custom fields',NULL,'カスタム項目はポータルごとの項目IDで扱い、文字列・数値・真偽・日付・画像をサポートする。別ポータルへのID流用は避ける必要がある。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0139','B05-20261011-REV021','B05-20261011-EV0139','Pay rates and salaries',NULL,'職員グループに紐づく時給とその履歴、固定給与の配賦設定をPay APIで扱う。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0140','B05-20261011-REV021','B05-20261011-EV0140','Contract rules',NULL,'Contract Rulesを取得して職員へ割り当て、週・月・年の契約時間ルールを連携する。実際の勤務制約の強制力はこのAPI案内だけでは確定しない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0141','B05-20261011-REV022','B05-20261011-EV0141','Pilot; certification',NULL,'デモ環境での開発後、原則2社の顧客でパイロットを行い、1社でも受け付けるとしている。ベンダーによるデモ上の設定確認を含む。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0142','B05-20261011-REV022','B05-20261011-EV0142','Documentation',NULL,'公開するサポート資料にデータフロー、認証、設定、FAQ・制限を含め、継続的な更新を求める。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0143','B05-20261011-REV022','B05-20261011-EV0143','Listing; marketing',NULL,'認証後の連携一覧掲載、対象市場に応じた翻訳、見込み顧客紹介や共同マーケティングの機会を説明する。再販権・報酬額の契約保証は未確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0144','B05-20261011-REV023','B05-20261011-EV0144','2026-09-29',NULL,'2026-09-29に部署内セクションの作成・更新・削除エンドポイントを追加。操作別スコープが必要で、更新時に色を省略すると元の色を保持する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0145','B05-20261011-REV023','B05-20261011-EV0145','2026-09-28',NULL,'2026-09-28に職員のセキュリティグループ所属取得を追加。全部署／指定部署と主所属部署条件を返し、専用参照スコープが必要。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0146','B05-20261011-REV023','B05-20261011-EV0146','2026-09-18',NULL,'2026-09-18の電話番号表現の不一致への対応は、新たに国番号なし項目を追加し、従来項目は変更しない方式。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0147','B05-20261011-REV023','B05-20261011-EV0147','2026-03-19',NULL,'2026-03-19の部署別給与識別子APIはPro契約が必要と明記。API全体のPlus対応を、この個別機能へ一律適用しない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0148','B05-20261011-REV023','B05-20261011-EV0148','2026-09-14',NULL,'2026-09-14にData Centerのデータセット取得・更新と数式評価APIの文書を公開。文書公開日を機能の初回提供日とは断定しない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0149','B05-20261011-REV023','B05-20261011-EV0149','2023-06-26 Get history of changes',NULL,'2023-06-26に勤務の変更履歴APIを追加し、変更日時と変更者を取得できる。保存期間・改ざん防止は未記載。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0150','B05-20261011-REV023','B05-20261011-EV0150','2023-06-26 Approve a shift for payroll',NULL,'給与向け勤務承認APIは打刻データを考慮しないと明記する。予定勤務を承認する処理で、打刻照合済みの給与結果とは区別する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0151','B05-20261011-REV023','B05-20261011-EV0151','2023-07-28',NULL,'スキルとSupervisor項目は2023年の説明でポータルへの有効化依頼が必要。標準で全アカウントに利用可能とは扱わない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0152','B05-20261011-REV023','B05-20261011-EV0152','2024-10-01',NULL,'2024-10-01以降X-OpenAPI-Regionヘッダーは無効と案内する。旧資料のEurope/Australia切替説明を現行API仕様として使わない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0153','B05-20261011-REV024','B05-20261011-EV0153','指定期間モードの概要',NULL,'暦月のほか1〜4週間の任意期間を指定し、その期間の勤務表をまとめて自動作成する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0154','B05-20261011-REV024','B05-20261011-EV0154','指定期間モードの概要',NULL,'勤務時間上限と勤務回数を設定期間の通算で判定する。4週間通算の所定上限を暦月に読み替えず設定できる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0155','B05-20261011-REV024','B05-20261011-EV0155','導入部',NULL,'4週間で8日休みがあるかを自動チェックすると説明する。前期間の夜勤・休息の引継ぎや個別労使協定の検証は未確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0156','B05-20261011-REV024','B05-20261011-EV0156','提供開始時期',NULL,'指定期間モードは2026-07-30より提供開始と記載する。対象契約・追加費用は問い合わせが必要。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0157','B05-20261011-REV025','B05-20261011-EV0157','Cares Connectとの連携',NULL,'作成した勤務表をブライトヴィーのCares Connectへ取り込む連携に対応したと発表する。双方向API同期とは記載されていない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0158','B05-20261011-REV025','B05-20261011-EV0158','勤怠システムとの連携',NULL,'勤怠向けCSVの列を任意に設定し、標準対応外の形式にも手動設定で対応する案内がある。2026-08-04時点で対応勤怠システム13種類。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0159','B05-20261011-REV026','B05-20261011-EV0159','タイムカードのデータダウンロード方法',NULL,'職員別の打刻日、出退勤時刻、休憩時間をCSVへ出力し、ファイル作成単位、タイトル行、スタッフコード、時間表示形式を選択できる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0160','B05-20261011-REV026','B05-20261011-EV0160','ダウンロードされないデータ',NULL,'不正打刻と未打刻データはCSVへ出力されない。出退勤が同時刻、休憩と勤務時刻の不整合などを不正例として挙げる。欠損を補完して出す仕様ではない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0161','B05-20261011-REV027','B05-20261011-EV0161','共有できるシフト／スタッフ',NULL,'共有できるのは確定シフトだけで、店舗全体の表も受信者を選択して連携済み職員のシフトボードへ送る。公開版の通知再送・到達確認は未確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0162','B05-20261011-REV027','B05-20261011-EV0162','レイアウト; ファイル形式',NULL,'PDFまたはExcelで日・週・月の3レイアウトを出力する。出力項目の個別追加・削除はできず、週のPDFだけメモを含められる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0163','B05-20261011-REV027','B05-20261011-EV0163','PDFまたはExcelファイルとして印刷',NULL,'勤務表を印刷して紙で配る手順がある。個人スマホなしで希望提出まで同等に行えるかは別確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0164','B05-20261011-REV028','B05-20261011-EV0164','スタッフデータ／シフトデータのCSV',NULL,'職員CSVに時給、日別交通費、職員コード、メモ、勤務表補足を追加。勤務データは職員別・グループ別の勤務数・時間数・パターン数集計もCSVへ出せる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0165','B05-20261011-REV028','B05-20261011-EV0165','他グループのシフトから編集',NULL,'複数グループ所属職員の勤務を他グループの表から編集できる。複数部署の同時最適化とは区別する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0166','B05-20261011-REV029','B05-20261011-EV0166','表示・ダウンロード制限の設定',NULL,'打刻実績管理への移動にパスワード制限を設定でき、さらに一般権限アカウントからのアクセス自体を禁止できる。対象画面に時給・概算給与・手当・交通費も含む。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0167','B05-20261011-REV030','B05-20261011-EV0167','Airワーク 給与支払へのデータ出力',NULL,'Airワーク 給与支払用の概算人件費データをCSVダウンロードし、同サービスへアップロードする手順を掲載する。リアルタイムAPI送信とは記載されない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0168','B05-20261011-REV030','B05-20261011-EV0168','freeeの給与計算で表示される項目',NULL,'freee人事労務の給与計算を連携しても、Airシフト側に表示するのは総支給、控除、差引支給と各合計のみ。詳細内訳はfreee側で確認する。人件費最適化機能の証拠ではない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0169','B05-20261011-REV030','B05-20261011-EV0169','Airメイトとの連携',NULL,'Airメイトに勤務・勤怠・概算人件費を連携し、Airレジの売上と合わせて分析する。Airレジ未利用でも分析は可能と説明する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0170','B05-20261011-REV031','B05-20261011-EV0170','費用 月額費用',NULL,'月額10万円からと掲載するが、欄内の参考時点は2024年2月。現在の個別契約額とは扱わない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0171','B05-20261011-REV031','B05-20261011-EV0171','業種別月額費用一例',NULL,'利用機能と登録従業員数によって変動。参考例は500人35万円、1500人75万円、300人24万円、700人50万円／月で、人数だけの固定単価には換算しない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0172','B05-20261011-REV031','B05-20261011-EV0172','初期費用',NULL,'初期費用は別途見積とする。月額掲載額に初期費用が含まれるとは推定しない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0173','B05-20261011-REV032','B05-20261011-EV0173','第2〜5項',NULL,'体験は小売・サービス業の実運営企業向けで最大2店舗、サイト情報送付から最大45日、登録職員数の制限なし。期間・利用機能は申込プランで変わる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0174','B05-20261011-REV032','B05-20261011-EV0174','第1項',NULL,'有償体験分は開始月の翌月初めに請求し、振込手数料は顧客負担とする。一般サブスクリプションの最低期間は未確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0175','B05-20261011-REV032','B05-20261011-EV0175','第6〜7項',NULL,'体験作業は操作マニュアルに沿って原則顧客が行い、ベンダーの準備・作業支援に実費が発生する場合は事前案内・相談すると記載する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0176','B05-20261011-REV032','B05-20261011-EV0176','第9・14項',NULL,'体験用ソフト・資料は本人利用に限定し、他社開示、ソフトの改変・解析、譲渡・転貸・販売を禁止する条項がある。公開ページの要約であり正式契約の法的評価ではない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0177','B05-20261011-REV032','B05-20261011-EV0177','特記事項',NULL,'訪問可能な地域では対面フォロー、それ以外はWeb会議で支援する。応答時間・無償範囲は記載されない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0178','B05-20261011-REV033','B05-20261011-EV0178','認証概要',NULL,'登録番号J0876、登録日2026-03-15、認証機関ASR、JIS Q 27001:2025（ISO/IEC 27001:2022+Amd 1:2024）を公表。範囲は顧客向けクラウド型課題解決システム提供に関するISMS。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0179','B05-20261011-REV034','B05-20261011-EV0179','Meet federal security standards',NULL,'米国内のSOC 2認証データセンターに顧客データを保存すると提供者が説明する。特定リージョン、バックアップ・処理地域は未記載。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0180','B05-20261011-REV034','B05-20261011-EV0180','Meet federal security standards',NULL,'SOC 2 attestation、HTTPS通信暗号化、FedRAMP Authorized、VA・IHSのATOを提供者が掲示する。FedRAMP登録簿や監査原本は未照合で、看護勤務表の全構成への認定適用は未確定。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0181','B05-20261011-REV034','B05-20261011-EV0181','Login Authentication',NULL,'連邦組織のSSOへSAMLで連携すると記載する。MFA強制、一般契約の料金・対象プランは未記載。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0182','B05-20261011-REV035','B05-20261011-EV0182','Support Phone; Shift Admin support',NULL,'電話、サポートケース、ヘルプセンターへの導線を掲載し、Shift Adminの支援は別窓口へ案内する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0183','B05-20261011-REV035','B05-20261011-EV0183','Security Disclaimer',NULL,'安全上、サポート担当は利用者メールアドレスの開示・変更、勤務表や給与の変更を行わないと明記する。全ベンダー操作権限の技術的証明とは別。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0184','B05-20261011-REV036','B05-20261011-EV0184','Logging in; Forgetting details',NULL,'ユーザー名入力後に顧客のSSOポータルへ遷移する。認証情報の再設定は顧客のIT部門等が行い、Rotageek支援側ではSSOパスワードを変更できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0185','B05-20261011-REV037','B05-20261011-EV0185','paths /api/v1/auth; securitySchemes',NULL,'API認証はpasswordまたはrefresh_token grantを扱い、Bearer JWTで接続する。画面のSSOとは別のAPI仕様。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0186','B05-20261011-REV037','B05-20261011-EV0186','paths /api/v1/audits/{entityType}/{entityId}',NULL,'エンティティ別監査ログをUTCの期間で抽出し、0起点のページ番号、1〜50件／ページ（既定30）、並べ替えを指定する。保存期間・改ざん耐性は未記載。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0187','B05-20261011-REV037','B05-20261011-EV0187','paths users; locations/users; users/skills; users/positions',NULL,'職員の作成・更新、外部IDの更新、所属拠点の追加・解除、スキル・ポジションの付与・解除を公開する。二重更新の整合性は実機未確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0188','B05-20261011-REV037','B05-20261011-EV0188','paths users/employeetypes; users/classifications; users/payrates',NULL,'職員の雇用区分、分類、賃金等は適用日別に取得・更新・削除するAPIを持つ。勤務表の最適化条件の全版再現とは別。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0189','B05-20261011-REV037','B05-20261011-EV0189','paths users/enddate/{proposedEndDate}/conflicts',NULL,'退職日変更前に将来勤務・休暇申請への影響件数と保持される確定勤怠をプレビューするAPIがある。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0190','B05-20261011-REV037','B05-20261011-EV0190','UpdateEndDateRequestModel; EndDateConflictResolution',NULL,'退職日の更新では将来勤務を空き枠へ変換するか削除するかを指定でき、退職日をnullにして再有効化するスキーマもある。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0191','B05-20261011-REV037','B05-20261011-EV0191','DELETE schedule/records/{recordId} description',NULL,'勤務削除APIは専用権限、勤務レコードであること、勤怠が未確定であることを検査後、画面削除と同じ業務処理へ委譲する。拠点権限、打刻済み検査、職員通知等も同じと説明する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0192','B05-20261011-REV037','B05-20261011-EV0192','paths availability; leave/requests; schedule',NULL,'勤務不可の期間指定取得・更新・削除、休暇申請の作成・更新、勤務表の拠点別／職員別参照を公開する。最適化ジョブ開始APIはこの仕様一覧で確認できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0193','B05-20261011-REV037','B05-20261011-EV0193','paths demand; budget',NULL,'必要量の原データと調整済み値の取得、明示需要の更新、拠点予算の金額／時間更新を公開する。最適化結果の根拠全体を返すとは推定しない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0194','B05-20261011-REV037','B05-20261011-EV0194','holidayentitlements/users/dataset1 and dataset2',NULL,'全職員の休暇権利データは事前計算済みテーブルの値で、実時間の再計算ではないと明記する。職員コード順にページングする。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0195','B05-20261011-REV037','B05-20261011-EV0195','WebhookEventName enum',NULL,'勤務承認、職員変更、勤怠確定、空き枠変更、給与処理、休暇変更、実績勤務更新、賃金変更の8Webhookイベント名をスキーマに定義する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0196','B05-20261011-REV038','B05-20261011-EV0196','Using webhooks; event examples',NULL,'Webhook登録後に最初の通知まで最大10分かかる場合がある。通知には時刻と一意IDがあり、通知を受けた後に勤務・職員・勤怠等をAPIで取得する方式。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0197','B05-20261011-REV038','B05-20261011-EV0197','Security',NULL,'Webhookはraw bodyと共有秘密でHMAC-SHA256署名を計算し、signatureヘッダーと照合する仕様。秘密はサーバーで暗号化して保持すると説明する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B05-20261011-OBS0198','B05-20261011-REV038','B05-20261011-EV0198','Security vs OpenAPI AddWebhookModel',NULL,'Webhook案内の秘密長は8〜256文字だが、取得した現行OpenAPIのAddWebhookModelは8〜128文字。上限を一方へ決めず、接続時の現行要件を確認する。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-CORR001','REV-B02-W205','B06-20261011-CORR001-EV1','アカウント削除',NULL,'職員の退会だけでは施設側の勤務表・提出希望は消えない。','supports','editorial_reclassification','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-CORR002','B03-20261011-REV031','B06-20261011-CORR002-EV1','引き継ぎ・出力',NULL,'勤務表はExcel・CSV・PDF出力。ただし全設定・監査履歴の一括搬出は確認できない。','supports','editorial_reclassification','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-CORR003','B03-20261011-REV002','B06-20261011-CORR003-EV1','クイックスタート・接続解除',NULL,'APIキーによる接続とOAuthによるリモートMCP接続を説明し、接続アプリは管理画面で解除可能。SSO/MFA全般の保証ではない。','supports','editorial_reclassification','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0001','B06-20261011-REV003','B06-20261011-EV0001','夜勤72時間ルール／対応範囲',NULL,'夜勤除外を「月16時間以下」と説明。行政様式の16時間未満・短時間正職員12時間未満・その他病棟8時間未満との照合が必要。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0002','B06-20261011-REV003','B06-20261011-EV0002','夜勤72時間ルール',NULL,'2病棟兼務は勤務割合で計上と説明するが、分子・分母、丸め、ゼロ除算の詳細は未開示。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0003','B06-20261011-REV003','B06-20261011-EV0003','勤務実績／取り込みと集計',NULL,'日勤・夜勤を施設の夜勤時間帯で分け、打刻を優先して遅刻早退・会議等を控除する。例外的に算入できる研修等への対応は不明。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0004','B06-20261011-REV003','B06-20261011-EV0004','FAQ 最新の様式',NULL,'改定にアップデートで追従と案内。算式の版固定・適用日・過去帳票再計算の扱いは不明。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0005','B06-20261011-REV003','B06-20261011-EV0005','施設全体で見る',NULL,'提出後のシフト変更で数値が変わった場合に警告すると案内。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0006','B06-20261011-REV003','B06-20261011-EV0006','施設全体で見る',NULL,'施設管理者の代行編集を記録すると案内。記録の全量搬出形式は不明。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0007','B06-20261011-REV030','B06-20261011-EV0007','ダウンロード入力フォーム',NULL,'無料Excelは施設名・担当者名・メール入力と同意を求める取得方式。実ファイルは未取得、数式は未検算。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0008','B06-20261011-REV001','B06-20261011-EV0008','PDF pp.2-4',NULL,'行政様式は月平均夜勤時間=(D-E)/B。Bは夜勤専従・所定の時間未満者を除き、病棟外兼務では夜勤割合で数える。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0009','B06-20261011-REV004','B06-20261011-EV0009','第3-14条',NULL,'規約第3-14条には施設解約時の全設定・履歴・監査ログの一括提供、形式、期限、費用の明記を確認できなかった。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0010','B06-20261011-REV004','B06-20261011-EV0010','第4条',NULL,'ゲストの個人予定は端末内のみ保存し、サーバー保存・バックアップを行わない。削除・初期化・機種変更時は復元できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0011','B06-20261011-REV004','B06-20261011-EV0011','第8条',NULL,'シフトの制度適合・人員充足の最終判断は施設責任とし、自動算出の要件適合を保証しない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0012','B06-20261011-REV004','B06-20261011-EV0012','第5条',NULL,'情報訂正・削除は原則所属施設へ申し出ると規定。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0013','B06-20261011-REV005','B06-20261011-EV0013','二要素認証の無効化',NULL,'PC版はシステム管理者のメール二要素認証が必須で無効化できないと明記。マネージャー・シフト管理者・スタッフは無効化可能。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0014','B06-20261011-REV005','B06-20261011-EV0014','マネージャー・シフト管理者',NULL,'マネージャー・シフト管理者はアカウント単位で任意設定し、登録メールへのコードで認証する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0015','B06-20261011-REV005','B06-20261011-EV0015','システム管理者',NULL,'認証メール再送・迷惑メール確認を案内。管理者ロックアウトからの復旧手続きは本文で確認できない。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0016','B06-20261011-REV006','B06-20261011-EV0016','更新情報／注意事項／無効化',NULL,'アプリ記事は管理者必須化と、権限を限定しないメール削除／無効化手順を併記。PC記事の管理者無効化不可と整合する条件は未確定。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0017','B06-20261011-REV006','B06-20261011-EV0017','注意事項',NULL,'二要素認証メールアドレスはユーザー間で重複登録できないと案内。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0018','B06-20261011-REV007','B06-20261011-EV0018','How to Enable／How 2FA Works',NULL,'Security設定で全管理者のダッシュボードアクセスに2FAを要求。ユーザー名・パスワードに加えSMSの一時PINを入力する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0019','B06-20261011-REV007','B06-20261011-EV0019','Basic Plan脚注',NULL,'2026-08-13ヘルプは2FAをBasicから利用可能と明記。Enterprise限定を示す旧ヘルプ・料金表と契約範囲の照合が必要。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0020','B06-20261011-REV008','B06-20261011-EV0020','Security',NULL,'2025-04-27のEnterprise説明では管理者2FAを追加セキュリティ機能とし4桁SMSを説明。新しいBasic脚注との差は未解消。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0021','B06-20261011-REV009','B06-20261011-EV0021','Prerequisites／Tip',NULL,'Azure AD SSOはEnterpriseが前提、設定できるのはownerのみ。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0022','B06-20261011-REV009','B06-20261011-EV0022','Adding SSO for Mobile',NULL,'全ユーザー・モバイルアプリへのSSO適用を選択可能。選択肢が表示されない場合はsupport対応を案内。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0023','B06-20261011-REV009','B06-20261011-EV0023','Login Process',NULL,'管理者は電話番号入力後にAzureへ転送。Azure側MFAの強制条件・ロックアウト復旧は未記載。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0024','B06-20261011-REV010','B06-20261011-EV0024','Which identity providers',NULL,'SP開始SAML2.0対応IdPが前提。Okta・Azure・PingIdentity・Oracleを例示し、OIDCは限定的ソーシャルSSOのみ。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0025','B06-20261011-REV010','B06-20261011-EV0025','enabled and required',NULL,'SSO enabledはパスワード・ソーシャル併用可、SSO requiredはそれらをログイン画面から除去する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0026','B06-20261011-REV010','B06-20261011-EV0026','If I have 2FA',NULL,'SSO経由ではDeputy内2FAを利用できずIdP側で設定する。Deputyのユーザー名・パスワード認証では2FAが継続する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0027','B06-20261011-REV010','B06-20261011-EV0027','Will employees need to re-login',NULL,'SSO requiredへの変更では既存セッションを直ちに再認証せず、ログアウト／有効期限まで継続する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0028','B06-20261011-REV010','B06-20261011-EV0028','identity providers',NULL,'同一インスタンス内でグループごとのSSO／非SSO分離は非対応と記載。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0029','B06-20261011-REV010','B06-20261011-EV0029','issues logging in',NULL,'ロックアウト時はSystem Adminにパスワード再設定またはsupport連絡、その他職員には管理者連絡を案内。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0030','B06-20261011-REV011','B06-20261011-EV0030','Enabling MFA',NULL,'管理者等の高権限ユーザーにはMFAを推奨し、個人プロフィールで有効化する。全管理者の一括強制設定は確認できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0031','B06-20261011-REV011','B06-20261011-EV0031','Disabling MFA',NULL,'XeroまたはMYOB連携中はMFA必須で無効化不可。解除するには先に連携を切断する必要がある。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0032','B06-20261011-REV011','B06-20261011-EV0032','FAQ4-5',NULL,'非連携時は個人プロフィールからMFA解除を案内。端末喪失時はsupportへ連絡し別方法の本人確認が必要な場合がある。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0033','B06-20261011-REV012','B06-20261011-EV0033','Verify your identity',NULL,'MFAコードは登録メールへ送信、同じコードをアプリpushへ同時送信。届かない場合はカウントダウン後にSMSを利用する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0034','B06-20261011-REV012','B06-20261011-EV0034','Setting up MFA',NULL,'Google Authenticator設定への案内も残る。メール／pushの現行主方式とTOTPの併用可否は実アカウントで未確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0035','B06-20261011-REV012','B06-20261011-EV0035','Updating your mobile number',NULL,'ログイン不能時の連絡先はmanager／admin。電話番号更新を支援すると説明。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0036','B06-20261011-REV013','B06-20261011-EV0036','About two-step verification',NULL,'全権限のユーザーが個別に二段階認証を有効化でき、有効化後は毎回ログインにコードが必要。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0037','B06-20261011-REV013','B06-20261011-EV0037','Methods／Login workflow',NULL,'認証アプリまたはSMSを利用し、全端末のログインでパスワード後にコードを確認する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0038','B06-20261011-REV013','B06-20261011-EV0038','Re-authentication requirements',NULL,'メールアドレス変更とPayrollの機密情報閲覧では再認証が必要。管理者全員への強制設定は本文にない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0039','B06-20261011-REV014','B06-20261011-EV0039','End-of-contract data extraction',NULL,'契約中はレポート機能で全量抽出可能と申告し、supportが移行・抽出を支援する。対象テーブル・添付・監査ログの詳細は未提示。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0040','B06-20261011-REV014','B06-20261011-EV0040','End-of-contract process',NULL,'終了時の追加料金はなく、アカウントは直ちに無効化されると記載。終了後の閲覧猶予は確認できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0041','B06-20261011-REV014','B06-20261011-EV0041','Data export formats／approach',NULL,'Employer HubからCSV・Excelへ出力できると申告。通常出力と契約出口の全量対象は同一とは限らない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0042','B06-20261011-REV014','B06-20261011-EV0042','User authentication／management interfaces',NULL,'ユーザーと管理インターフェースの認証欄はユーザー名・パスワードを列挙。管理者MFAの記載は確認できない。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0043','B06-20261011-REV014','B06-20261011-EV0043','Audit information',NULL,'利用者・supplier監査はリアルタイム提供、各12か月以上保持。システムログも12か月以上と申告。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0044','B06-20261011-REV014','B06-20261011-EV0044','Data storage and processing locations',NULL,'ホスティングは英国。顧客による保管場所の選択はできないと申告。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0045','B06-20261011-REV014','B06-20261011-EV0045','API／API documentation',NULL,'Swagger・sandboxを持つAPIでESR、job planning、bank、VMS連携を案内。専任integrationチームが実装を支援。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0046','B06-20261011-REV015','B06-20261011-EV0046','End-of-contract data extraction',NULL,'システム内の全データを顧客所有とし、要請に応じSQL等の標準形式で返却すると申告。全テーブル・添付・監査の具体的範囲は未開示。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0047','B06-20261011-REV015','B06-20261011-EV0047','End-of-contract process',NULL,'顧客が契約終了前／終了時に用意されたツールで抽出する責任を持ち、抽出しなかった損失には責任を負わないと記載。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0048','B06-20261011-REV015','B06-20261011-EV0048','End-of-contract process',NULL,'終了後1か月以内に返却を求めない場合は顧客データを削除すると記載。バックアップ残存期限・消去証明は不明。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0049','B06-20261011-REV015','B06-20261011-EV0049','Access restrictions in management interfaces／User authentication',NULL,'管理インターフェースへのアクセスに二要素認証を列挙し、ADFSとの連携も案内。強制・解除・復旧条件の詳細は未記載。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0050','B06-20261011-REV015','B06-20261011-EV0050','Audit information',NULL,'利用者監査とシステムログの保持は顧客定義、supplier監査は定期報告で12か月以上と申告。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0051','B06-20261011-REV015','B06-20261011-EV0051','API',NULL,'AISはODataの外向き公開とInbound Data Packsの定期投入を説明。フィールド対応・ページング・bundle単位の仕様がある。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0052','B06-20261011-REV016','B06-20261011-EV0052','End-of-contract data extraction／process',NULL,'終了時は画面・レポートへのアクセスとデータ抽出協力を案内。全設定・履歴・添付の一括提供、期限、費用は確認できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0053','B06-20261011-REV016','B06-20261011-EV0053','Data export formats／approach',NULL,'出力形式欄はCSV・Excel・JSONを列挙するが、出力方法欄はSonaへの取込を説明している。実際の出口仕様は照合が必要。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0054','B06-20261011-REV016','B06-20261011-EV0054','User authentication／management interfaces',NULL,'利用者・管理画面の認証欄は二要素認証を列挙。管理者全員への強制、方式、解除・復旧手順は未開示。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0055','B06-20261011-REV016','B06-20261011-EV0055','Audit information',NULL,'利用者監査はリアルタイム、supplier監査は要請で提供し各12か月以上。システムログ保持は顧客定義と申告。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0056','B06-20261011-REV016','B06-20261011-EV0056','Data storage and processing locations',NULL,'データ処理・保管は英国で顧客が場所を選べると申告。現行契約の具体リージョンは要確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0057','B06-20261011-REV016','B06-20261011-EV0057','Protecting data at rest／ISO/IEC 27001 certification',NULL,'保存時暗号化AES256を申告。G-Cloud 14ではISO27001取得準備中と記載し、現在の取得状況は本文だけでは確定できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0058','B06-20261011-REV017','B06-20261011-EV0058','6.3.7, pp.7-8',NULL,'終了時は書面指示により個人データと複製を返却／削除する。ただし法令上必要な保持を除外し、全DBの形式・納期は明記しない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0059','B06-20261011-REV017','B06-20261011-EV0059','6.3.7',NULL,'削除の定義はデータを使用不能にすることを含む。物理的な全媒体消去や即時バックアップ消去の保証とは区別が必要。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0060','B06-20261011-REV017','B06-20261011-EV0060','15.4.4, p.10',NULL,'終了後の合理的期間内に秘密情報の返却／破棄を要請できるが、未払料金がある場合は非個人データの返却義務を免れる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0061','B06-20261011-REV017','B06-20261011-EV0061','15.1／15.4',NULL,'初期／更新期間末の終了には6か月前の通知を規定。終了時はライセンスが直ちに消滅する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0062','B06-20261011-REV017','B06-20261011-EV0062','6.5',NULL,'匿名集計データを内部分析・サービス改善に使う条項がある。外部AIへの送信・学習条件は明記しない。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0063','B06-20261011-REV018','B06-20261011-EV0063','End-of-contract data extraction',NULL,'終了時は要請に応じ合意形式で抽出すると申告。全履歴・設定・添付の範囲、費用、納期は未提示。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0064','B06-20261011-REV018','B06-20261011-EV0064','End-of-contract process',NULL,'契約終了2か月前に更新条件を提示し、期間末にアクセスを解除すると記載。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0065','B06-20261011-REV018','B06-20261011-EV0065','Data export formats／approach',NULL,'CSV出力はservice teamへの依頼で対応。オンライン閲覧・印刷も案内する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0066','B06-20261011-REV018','B06-20261011-EV0066','User authentication／management interfaces',NULL,'ユーザーと管理画面の認証で二要素認証を列挙。管理者の強制・解除・復旧条件は未記載。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0067','B06-20261011-REV018','B06-20261011-EV0067','Audit information',NULL,'利用者・supplier監査はsupport依頼で提供し12か月以上保持。システムログは1〜6か月と申告。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0068','B06-20261011-REV018','B06-20261011-EV0068','Getting started',NULL,'InGenius導入は専任担当と受入基準を合意し、技術チームが管理者・臨床職の承認まで反復する支援を説明。自己操作のみの自動生成とは区別する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0069','B06-20261011-REV019','B06-20261011-EV0069','様式9',NULL,'様式9出力の案内はあるが、月平均夜勤時間の分母・除外閾値・兼務按分・丸めの算式は本文にない。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0070','B06-20261011-REV019','B06-20261011-EV0070','様式9',NULL,'公開機能ページでは対象の令和8年度様式・施行日・版固定を確認できない。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0071','B06-20261011-REV020','B06-20261011-EV0071','様式9完全対応',NULL,'保団連とNTTデータセキスイの共同作成Excelと同じ帳票を使用と説明するが、製品の除外閾値・按分・丸めの処理は未開示。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0072','B06-20261011-REV020','B06-20261011-EV0072','様式9完全対応',NULL,'公開ページでは製品が使用する共同Excelの版・改定適用日を確認できない。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0073','B06-20261011-REV020','B06-20261011-EV0073','Excel連携',NULL,'予定表・マスタ等のほとんどの画面をExcelへコピーできると案内。一括の全設定・履歴搬出ではない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0074','B06-20261011-REV021','B06-20261011-EV0074','勤務表／様式9',NULL,'勤務表は4週／月単位を選び、複数月から任意の1か月以内を切り出せると説明。申請対象期間との整合は別途確認が必要。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0075','B06-20261011-REV021','B06-20261011-EV0075','様式9',NULL,'自作Excel様式にセル位置を指定して出力できると案内。帳票レイアウト変更と制度算式の更新保証を区別する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0076','B06-20261011-REV021','B06-20261011-EV0076','様式9',NULL,'概要では夜勤除外閾値・兼務の分母・端数処理の式を確認できない。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0077','B06-20261011-REV022','B06-20261011-EV0077','法改正への対応',NULL,'診療報酬改定に迅速に対応すると案内。対象版・更新日・旧帳票再計算の扱いは示されていない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0078','B06-20261011-REV022','B06-20261011-EV0078','FAQ本文',NULL,'FAQでは令和8年度の除外閾値・兼務按分・丸めの詳細算式を確認できない。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0079','B06-20261011-REV023','B06-20261011-EV0079','第37条7項／第38条2項',NULL,'要請時に秘密情報の資料を返還し蓄積情報を消去する規定はあるが、設定・全履歴・監査ログの一括提供形式と費用は未明記。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0080','B06-20261011-REV023','B06-20261011-EV0080','第37条7-8項／第38条',NULL,'相手方の要請で秘密情報を完全消去する条項を個人情報にも準用。秘密保持は終了後1年、個人情報条項は終了後も存続。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0081','B06-20261011-REV023','B06-20261011-EV0081','第40条7項',NULL,'適用法令・業界規則への適合を利用者の責任で調査し、サービスの法令適合を保証しないと規定。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0082','B06-20261011-REV024','B06-20261011-EV0082','Before cancelling',NULL,'解約前に履歴をData Exporterで出力し、News・Training等のアップロードファイルは別に保存するよう案内。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0083','B06-20261011-REV024','B06-20261011-EV0083','Subscription billing',NULL,'月払い／年払いとも解約後すぐアクセスを失う。年払いの未使用期間は返金しないと説明し、HR・Analyticsは別に解約する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0084','B06-20261011-REV024','B06-20261011-EV0084','Delete your business',NULL,'business削除は解約済みかtrialで可能と説明。削除すると全履歴が永久に失われ、復元できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0085','B06-20261011-REV025','B06-20261011-EV0085','Data source／System Administrator',NULL,'System Administratorがデータ種別を選んでCSV抽出。従業員・契約履歴・勤務・休暇ルール・給与ルール・SMSログ等を列挙する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0086','B06-20261011-REV025','B06-20261011-EV0086','Step 2-4',NULL,'期間、全／特定職員、全／特定拠点、version付き履歴の有無を選べ、対象件数を表示し管理者へダウンロード通知する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0087','B06-20261011-REV025','B06-20261011-EV0087','IMPORTANT',NULL,'退去用CSVは一括更新・再取込用の形式と一致しないと注意。全設定・添付・監査ログの欠落なく再構成できるかは未検証。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0088','B06-20261011-REV025','B06-20261011-EV0088','Deputy APIs',NULL,'複雑な抽出要件にはAPIとIT担当による出力を案内。Exporterの全種別を一括処理する保証とは別。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0089','B06-20261011-REV026','B06-20261011-EV0089','Refunds',NULL,'全額返金の場合はアカウントをブロックするため、必要な情報を事前にExcel／PDFで出力するよう案内。全設定・監査の一括形式は未提示。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0090','B06-20261011-REV026','B06-20261011-EV0090','Annual／Monthly subscriptions',NULL,'年払いBasic／Advanced／Expertの最初30日内は残月の按分返金条件を説明。月払いは期間末まで利用でき、返金なしとする。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0091','B06-20261011-REV027','B06-20261011-EV0091','12.1／12.3',NULL,'解約後は顧客データへアクセスできず、勤務表・timesheet等を解約前に出力するよう規定。全設定・履歴の返却義務は確認できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0092','B06-20261011-REV027','B06-20261011-EV0092','12.1／12.3',NULL,'12.1は削除要請まで保持し得るとし、12.3は終了後の合理的期間内に難読化・削除・除去を規定。法令等の保持例外と共有済みデータの留保がある。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0093','B06-20261011-REV027','B06-20261011-EV0093','12.1',NULL,'Account & Billingから解約し、電話・メールだけでは成立しない。解約は即時有効で返金しないと規定。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0094','B06-20261011-REV027','B06-20261011-EV0094','4.2',NULL,'業務規約は健康・医療情報やHIPAA対象情報の入力を禁止し、必要最小限の情報のみ提供するよう規定。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0095','B06-20261011-REV027','B06-20261011-EV0095','4.1',NULL,'顧客データの匿名集計を分析・研究開発に利用する条項がある。外部AI学習への送信の具体条件は記載しない。','context','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0096','B06-20261011-REV028','B06-20261011-EV0096','Introduction／sections1-9',NULL,'解約時に備え、従業員、勤務、勤怠、休暇、TOIL等を各画面で保存する手順を案内。設定・全監査をまとめた単一dumpは示さない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0097','B06-20261011-REV028','B06-20261011-EV0097','Contracts／Documents overview',NULL,'署名済み契約書は1件ずつdownload。documents overviewは一覧のみで、元ファイルの一括取得ではない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0098','B06-20261011-REV028','B06-20261011-EV0098','Employee changes／Shift history',NULL,'従業員変更レポートは誰がいつ変更したかを出力。shift historyは画面参照を案内し、全履歴の一括出力は明示しない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0099','B06-20261011-REV028','B06-20261011-EV0099','Leave accounts／Leave requests／Transferred hours',NULL,'休暇・移送時間等のレポートは期間・状態・所属等で絞るため、全量保存には条件と各画面の漏れ確認が必要。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0100','B06-20261011-REV029','B06-20261011-EV0100','Activation／configuration',NULL,'MFAは任意の追加機能で、署名済み契約と請求書により有効化し、設定変更はQuinyxのみが行う。顧客の自己設定ではない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0101','B06-20261011-REV029','B06-20261011-EV0101','SMS／wrong code',NULL,'SMSの6桁コードに有効期限を設け、5回失敗するとアカウントをロックする。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0102','B06-20261011-REV029','B06-20261011-EV0102','How often',NULL,'認証頻度は毎回または7・30・60日ごとを選ぶと説明。全管理者のみの強制範囲・免除・復旧手順は本文にない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0103','B06-20261011-REV029','B06-20261011-EV0103','Cost',NULL,'月額利用料とSMS配信の追加従量費を記載するが金額は未開示。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0104','B06-20261011-REV029','B06-20261011-EV0104','Phone number',NULL,'SMS用電話番号は国際形式E.164、最大15桁を要求する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0105','B06-20261011-REV030','B06-20261011-EV0105','更新履歴',NULL,'公開更新履歴は2026-08-23に令和8年度版を公開、08-27に入力セル保護と人数枠更新。製品内の算式版とは同一と断定しない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0106','B06-20261011-REV030','B06-20261011-EV0106','人数枠／Excelの中身',NULL,'配布版は5シート、看護職員100名・看護補助者20名・その他20名。予実シートは参考のみで編集・計算に使用しない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0107','B06-20261011-REV031','B06-20261011-EV0107','2026年10月6日',NULL,'共同提供元は2026-10-06に26_9chiiki_ryoyo_hojokasan.xlsを整合性確認のため公開停止。NEO製品内の採用版・影響は未確認。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0108','B06-20261011-REV031','B06-20261011-EV0108','2026年5月27日',NULL,'2026-05-27案内は未届出項目の一部#VALUE!／#DIV/0!を要件に影響しない表示として注意追記。対象項目と版を切り分ける必要がある。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0109','B06-20261011-REV032','B06-20261011-EV0109','p.7',NULL,'2026手引きは4週を選べるのは月平均夜勤時間だけとし、配置数は暦月の実績が必要。4週と暦月の両帳票、空白のない周期を要求する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0110','B06-20261011-REV033','B06-20261011-EV0110','Important information',NULL,'MFAは既定で無効。有効化するとワークスペース全員に適用し個人除外は不可、Xero連携時は必須と明記。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0111','B06-20261011-REV033','B06-20261011-EV0111','Enable or disable',NULL,'認証アプリ／SMSを許可・無効化でき、方式解除は設定済み全職員へ適用。残る方式があれば次回ログインで再設定する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0112','B06-20261011-REV033','B06-20261011-EV0112','Login process',NULL,'SMS認証に追加料金はなく、プロフィールと異なる番号も登録可。認証アプリはQR／設定コードを利用。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0113','B06-20261011-REV033','B06-20261011-EV0113','Remember me',NULL,'30日間の認証省略は複数端末でも適用。未選択では次回ログインにもMFAを要求する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0114','B06-20261011-REV033','B06-20261011-EV0114','How to reset MFA',NULL,'Admin・HR managerが職員MFAをリセットし、次回ログインで再設定。管理者全員が入れない場合の復旧は未記載。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0115','B06-20261011-REV034','B06-20261011-EV0115','Cancellation period',NULL,'Starterは1か月、Plus・Proは12か月のcommitmentと説明。一般条件は更新1か月前までの解約申出を要求する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0116','B06-20261011-REV034','B06-20261011-EV0116','How to cancel',NULL,'通常は中途解約不可、解約後も請求期間／契約期末まで有効。四半期請求では当該四半期末の扱いを示す。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0117','B06-20261011-REV034','B06-20261011-EV0117','After cancellation',NULL,'解約後120日以内にworkspaceデータを削除し、それ以前の契約再開の連絡を例外として案内。起算日の個別契約との照合は未実施。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0118','B06-20261011-REV034','B06-20261011-EV0118','How to cancel／How to contact',NULL,'画面で解約できるのはAccount adminまたは登録者。supportへの申出は管理者等から行い、送受信日を解約申出日にする。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0119','B06-20261011-REV035','B06-20261011-EV0119','Entropy／Configuration',NULL,'職員と管理者で異なるパスワードentropy最低値を設定し、基準未達の保存を拒否する。高度設定有効化後は旧方式へ戻せない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0120','B06-20261011-REV035','B06-20261011-EV0120','As a manager',NULL,'managerはPeopleで職員に一時パスワードを設定でき、次回ログインで変更させる。MFAロック解除の手順とは区別する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0121','B06-20261011-REV035','B06-20261011-EV0121','Introduction',NULL,'OWASP ASVS level2への準拠は目標と表現。独立した適合認証の取得と解釈しない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0122','B06-20261011-REV036','B06-20261011-EV0122','Multi-factor Authentication',NULL,'管理者・manager等のユーザー区分ごとにMFA対象を選び、認証アプリまたはメールコードを要求する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0123','B06-20261011-REV036','B06-20261011-EV0123','Operational tips',NULL,'Company SettingsでMFAを一時的に無効化できると説明。管理者強制を解除不能とは扱えない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0124','B06-20261011-REV036','B06-20261011-EV0124','Operational tips',NULL,'設定途中で進んでロックアウトした利用者には管理者によるMFA情報リセットが必要となる場合がある。内部詳細手順は未公開。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0125','B06-20261011-REV036','B06-20261011-EV0125','Authorised Devices',NULL,'端末承認権限を持つ管理者等が端末と拠点を関連付け、web打刻を承認端末に限定できる。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0126','B06-20261011-REV037','B06-20261011-EV0126','I don’t have access to my device',NULL,'認証アプリを利用できない場合は社内管理者への連絡を案内。全管理者が入れない場合の復旧条件は未記載。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0127','B06-20261011-REV038','B06-20261011-EV0127','Step 1-3',NULL,'初期登録でメール方式を選べる。認証アプリのQR登録前にNextを押すとQR再生成されずロックアウトすると注意する。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0128','B06-20261011-REV039','B06-20261011-EV0128','Forgetting Single Sign On Details',NULL,'SSOログイン資格情報の再設定は顧客IdP／社内ITの担当。Rotageek supportはSSOパスワードを再設定できない。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0129','B06-20261011-REV040','B06-20261011-EV0129','Two Factor Authentication／Recovery Code Used',NULL,'認証アプリと1回限りのbackup codeの案内文言がある。使用後は2FA再設定、できなければ管理者連絡を示す。','supports','official_page_body_review','2026-10-11');
INSERT INTO "observation_evidence" ("observation_id","revision_id","evidence_id","locator","short_excerpt","paraphrase","stance","method","checked_on") VALUES ('B06-20261011-OBS0130','B06-20261011-REV040','B06-20261011-EV0130','公開ログイン本文',NULL,'公開ログインページ本文だけでは管理者MFAの一括必須化・プラン制限・SSOとの併用条件を確認できない。','context','official_page_body_review','2026-10-11');
